// Successful native gates/callbacks intentionally live until this script ends.
// Reverting Java hooks cannot prove every ordinary JNI call has returned yet.
const retainedNativeTransactionGates = [];

export function installNativeTransactionCodeFilter (mangler, implementation, code, vm) {
  if (!Number.isInteger(code) || code < 0 || code > 0x7fffffff) {
    throw new Error('Native transaction code is outside the positive jint ABI');
  }
  if (getApi().flavor !== 'art' || mangler.originalMethod === null || mangler.replacementMethodId === null) {
    throw new Error('A live ART method replacement is required');
  }
  const prior = mangler._nativeTransactionGate;
  if (prior !== undefined) {
    if (!prior.active || prior.code !== code) throw new Error('Native transaction gate identity changed');
    return prior.gate;
  }
  if (mangler.replacementMethodId.equals(mangler.methodId) || mangler.replacementMethodId.equals(mangler.hookedMethodId)) {
    throw new Error('Native transaction filter requires this bridge private ArtMethod clone');
  }
  const flags = mangler.originalMethod.accessFlags;
  // The public shape proof already requires an instance method with Parcel
  // references. Actual CriticalNative requires static/primitive-only shape.
  // Do not reinterpret OEM/ART Nterp bits through a historical Critical mask.
  if ((flags & kAccNative) === 0 || (flags & (kAccStatic | kAccFastNative)) !== 0 ||
      !mangler.hookedMethodId.equals(mangler.methodId)) {
    throw new Error('Ordinary instance JNI registration is not proved');
  }
  const original = mangler.originalMethod.jniCode;
  const owner = Process.findModuleByAddress(original);
  const range = Process.findRangeByAddress(original);
  if (owner === null || range === null || !range.protection.includes('x') || owner.name === 'libart.so' ||
      !/^\/(?:apex|system|system_ext|vendor|product)\//.test(owner.path)) {
    throw new Error('Registered JNI entry has no executable system module identity');
  }
  const slot = mangler.replacementMethodId.add(getArtMethodSpec(vm).offset.jniCode);
  if (!slot.and(pointerSize - 1).isNull() || !slot.readPointer().equals(implementation)) {
    throw new Error('Replacement JNI slot does not belong to this implementation');
  }
  const selected = Memory.alloc(4); selected.writeS32(code);
  const counters = Memory.alloc(8); counters.writeU32(0); counters.add(4).writeU32(0);
  const cm = new CModule(`
#include <glib.h>
extern gint selected_code;
extern guint8 original_transact(gpointer,gpointer,gint,gpointer,gpointer,gint);
extern guint8 guarded_transact(gpointer,gpointer,gint,gpointer,gpointer,gint);
extern volatile gint ordinary_count;
extern volatile gint matched_count;
guint8 transact_filter(gpointer env,gpointer self,gint code,gpointer data,gpointer reply,gint flags) {
  if (code != selected_code) {
    g_atomic_int_add(&ordinary_count,1);
    return original_transact(env,self,code,data,reply,flags);
  }
  g_atomic_int_add(&matched_count,1);
  return guarded_transact(env,self,code,data,reply,flags);
}
guint read_ordinary(void) { return (guint)g_atomic_int_add(&ordinary_count,0); }
guint read_matched(void) { return (guint)g_atomic_int_add(&matched_count,0); }
/* Only this script manages this private ArtMethod clone. With ART threads
 * stopped there is no legitimate concurrent writer between these seqcst RMWs. */
gint publish_filter(gpointer slot,gpointer expected,gpointer replacement) {
  gssize observed = g_atomic_pointer_add(slot,0);
  if ((gpointer)observed != expected) return 0;
  gssize previous = g_atomic_pointer_add(slot,(gssize)((guintptr)replacement-(guintptr)expected));
  return (gpointer)previous == expected ? 1 : -1;
}
`, { selected_code: selected, ordinary_count: counters, matched_count: counters.add(4),
  original_transact: original, guarded_transact: implementation });
  const entry = cm.transact_filter;
  const ordinary = new NativeFunction(cm.read_ordinary, 'uint', []);
  const matched = new NativeFunction(cm.read_matched, 'uint', []);
  const publish = new NativeFunction(cm.publish_filter, 'int', ['pointer', 'pointer', 'pointer']);
  // Resolve the helper's API and cause string outside the suspended body.
  const threadApi = getApi();
  if (threadApi['art::ThreadList::SuspendAll'] === undefined || threadApi['art::ThreadList::ResumeAll'] === undefined) {
    cm.dispose(); throw new Error('ART exclusive suspension API unavailable for JNI publication');
  }
  // Process range enumeration can omit this runtime's own CModule allocation.
  // Prove the exact compiled counter/publisher routines with no Binder calls,
  // only an external private scratch pointer. Do all probes before ART STW.
  if (ordinary() !== 0 || matched() !== 0) {
    cm.dispose(); throw new Error('Compiled native transaction counter self-test failed');
  }
  const scratch = Memory.alloc(pointerSize); scratch.writePointer(implementation);
  if (publish(scratch, NULL, entry) !== 0 || !scratch.readPointer().equals(implementation) ||
      publish(scratch, implementation, entry) !== 1 || !scratch.readPointer().equals(entry)) {
    cm.dispose(); throw new Error('Compiled native transaction publisher self-test failed');
  }
  const state = { active: false, code, cm, implementation, selected, counters, gate: null };
  const gate = { mode: 'native_code_filter', inspect() {
    return { ready: state.active, mode: 'native_code_filter', code,
      native_fastpass: ordinary(), native_matched: matched(), counter_bits: 32,
      original_jni_module: owner.name, original_jni_path: owner.path,
      original_jni_rva: original.sub(owner.base).toString(), retained_until_script_end: true };
  }};
  state.gate = gate;
  // Root code/callbacks before the one aligned pointer publication. Ordinary
  // callers bypass JS/pendingCalls, so no successful gate is explicitly freed.
  retainedNativeTransactionGates.push(state);
  let published = 0;
  withAllArtThreadsSuspended(() => { published = publish(slot, implementation, entry); });
  if (published !== 1) throw new Error('Private JNI clone ownership changed during atomic publication');
  state.active = true;
  mangler._nativeTransactionGate = state;
  return gate;
}

class ArtMethodMangler {

function verifyNativeTransactionFilterMethod (method) {
  const [name, holder, type, _id, ret, args] = method._p;
  if (name !== 'transactNative' || holder.$n !== 'android.os.BinderProxy' || type !== INSTANCE_METHOD ||
      ret.className !== 'boolean' || args.map(t => t.className).join(',') !== 'int,android.os.Parcel,android.os.Parcel,int' ||
      String(holder.class.getName()) !== 'android.os.BinderProxy') {
    throw new Error('Native code filter accepts only the BinderProxy transaction ABI');
  }
  const loader = holder.class.getClassLoader();
  if (loader !== null && String(loader.getClass().getName()) !== 'java.lang.BootClassLoader') {
    throw new Error('Native BinderProxy is not a boot class');
  }
}

function makeMethodCallable () {

methodPrototype = Object.create(Function.prototype, {
  installNativeTransactionCodeFilter: {
    value (code) {
      verifyNativeTransactionFilterMethod(this);
      const replacement = this._r;
      if (replacement === undefined || replacement._m === undefined) throw new Error('Install the Java transaction implementation first');
      return android.installNativeTransactionCodeFilter(replacement._m, replacement, code, vm);
    }
  },
  setNativeCodeFilter: {
    value (handler, code) {
      verifyNativeTransactionFilterMethod(this);
      if (typeof handler !== 'function') throw new TypeError('Native code filter handler must be a function');
      this.implementation = handler;
      try { return this.installNativeTransactionCodeFilter(code); }
      catch (failure) {
        // Reset through the original setter even after a failed publication.
        // This retires its private clone and leaves one complete Java guard.
        this.implementation = handler;
        // The original Java setter/exception marshaler remains fully active.
        const error = String(failure), method = this, installedReplacement = this.implementation;
        return { mode: 'java_replacement', error, inspect() {
          return { ready: method.implementation === installedReplacement, mode: 'java_replacement', error };
        }};
      }
    }
  },

implementation: MethodImplementation<Holder, Params, Return> | null;

/** hnubl scoped: only the ordinary boot-class BinderProxy JNI ABI. */
installNativeTransactionCodeFilter(code: number): NativeTransactionGate;
setNativeCodeFilter(handler: MethodImplementation<Holder, Params, Return>, code: number): NativeTransactionGate;

interface NativeTransactionGate {
    mode: 'native_code_filter' | 'java_replacement';
    error?: string;
    inspect(): { ready: boolean; mode: string; code?: number; native_fastpass?: number;
        native_matched?: number; counter_bits?: number; error?: string;
        original_jni_module?: string; original_jni_path?: string; original_jni_rva?: string;
        retained_until_script_end?: boolean };
}

